<?php require __DIR__.'/_layout.php';x1_require_role('admin');$db=x1_db();$msg='';$uploadDir=X1_ROOT.'/uploads/apk';if(!is_dir($uploadDir))@mkdir($uploadDir,0770,true);if($_SERVER['REQUEST_METHOD']==='POST'){try{x1_check_csrf();if(!$db)throw new RuntimeException('SQLite required');$act=(string)($_POST['act']??'upload');if($act==='upload'){if(empty($_FILES['apk']['tmp_name'])||!is_uploaded_file($_FILES['apk']['tmp_name']))throw new RuntimeException('APK upload missing');$version=preg_replace('/[^A-Za-z0-9._-]/','_',trim((string)$_POST['version_name']));$file='waveo-'.$version.'-'.date('Ymd-His').'.apk';$dest=$uploadDir.'/'.$file;if(!move_uploaded_file($_FILES['apk']['tmp_name'],$dest))throw new RuntimeException('Upload failed');$sha=hash_file('sha256',$dest);x1_db_exec('INSERT INTO apk_releases(id,version_name,version_code,channel,file_name,file_path,sha256,file_size,rollout_percent,status,notes,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[x1_id(),$version,(int)$_POST['version_code'],(string)$_POST['channel'],$file,'uploads/apk/'.$file,$sha,filesize($dest),max(0,min(100,(int)$_POST['rollout_percent'])),'active',trim((string)$_POST['notes']),date('c')]);x1_audit('apk_upload',$version);}elseif($act==='rollout'){x1_db_exec('UPDATE apk_releases SET rollout_percent=?,status=? WHERE id=?',[max(0,min(100,(int)$_POST['rollout_percent'])),(string)$_POST['status'],(string)$_POST['id']]);x1_audit('apk_rollout',(string)$_POST['id']);}header('Location:apk_manager.php');exit;}catch(Throwable $e){$msg=$e->getMessage();}}$rows=$db?x1_db_all('SELECT * FROM apk_releases ORDER BY created_at DESC'):[];top('APK Manager');?><section class="card hero"><div class=eyebrow>APK RELEASE CONTROL</div><h2><?=tr('Version, checksum, channels, staged rollout and rollback state','Versão, checksum, canais, rollout gradual e estado de rollback')?></h2></section><?php if($msg):?><section class="notice warn"><?=h($msg)?></section><?php endif?><section class=section><form method=post enctype=multipart/form-data><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=upload><div class=formgrid><label>APK<input type=file name=apk accept=".apk" required></label><label>Version Name<input name=version_name required></label><label>Version Code<input type=number name=version_code value=0></label><label>Channel<select name=channel><option>stable</option><option>beta</option><option>canary</option></select></label><label>Rollout %<input type=number min=0 max=100 name=rollout_percent value=100></label><label>Notes<textarea name=notes></textarea></label></div><button><?=tr('Upload release','Carregar release')?></button></form></section><section class=section><table><tr><th>Version</th><th>Channel</th><th>Size</th><th>SHA-256</th><th>Rollout</th><th>Status</th><th></th></tr><?php foreach($rows as $x):?><tr><td><?=h($x['version_name'])?></td><td><?=h($x['channel'])?></td><td><?=number_format((int)$x['file_size'])?></td><td><code><?=h(substr($x['sha256'],0,20))?>…</code></td><td><?=h($x['rollout_percent'])?>%</td><td><?=h($x['status'])?></td><td><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=rollout><input type=hidden name=id value="<?=h($x['id'])?>"><input type=number min=0 max=100 name=rollout_percent value="<?=h($x['rollout_percent'])?>"><select name=status><option value=active>active</option><option value=paused>paused</option><option value=rolled_back>rolled_back</option></select><button><?=tr('Apply','Aplicar')?></button></form></td></tr><?php endforeach?></table></section><?php bottom();